import { useCallback, useEffect, useRef, useState } from "react";
import { useActionQuery } from "../use-action.js";
import { DEFAULT_MEMBER_SEARCH_DEBOUNCE_MS, DEFAULT_MEMBER_SUGGESTION_LIMIT, extractShareErrorMessage, optimisticallyUpdateShareCache, rollbackShareCache, useShareOrgMemberSearch, useShareMutationGuard, useShareMutations, useShareQuery, } from "./share-controller-helpers.js";
export function useShareButtonController(options) {
    const [open, setOpen] = useState(false);
    const [inviteEmail, setInviteEmail] = useState("");
    const [selectedGroup, setSelectedGroup] = useState(null);
    const shareTabDefaultValue = options.shareTabs?.defaultValue ?? "share";
    const [activeShareTab, setActiveShareTab] = useState(shareTabDefaultValue);
    const [visibilityOverride, setVisibilityOverride] = useState(null);
    const appliedDefaultOpenRef = useRef(false);
    const { queryKey: shareQueryKey, query: sharesQuery, queryClient, } = useShareQuery(options.resourceType, options.resourceId);
    const { setVisibility, share, unshare } = useShareMutations();
    const visibilityGuard = useShareMutationGuard();
    const data = sharesQuery.data;
    const canManage = data?.role === "owner" || data?.role === "admin";
    const [shareError, setShareError] = useState(null);
    const handleOpenChange = useCallback((nextOpen) => {
        setOpen(nextOpen);
        options.onOpenChange?.(nextOpen);
        if (nextOpen) {
            setActiveShareTab(shareTabDefaultValue);
            options.shareTabs?.onValueChange?.(shareTabDefaultValue);
            if (visibilityOverride === null)
                void sharesQuery.refetch();
        }
    }, [options, shareTabDefaultValue, sharesQuery, visibilityOverride]);
    useEffect(() => {
        setInviteEmail("");
        setSelectedGroup(null);
        setShareMessage("");
        setMessageOpen(false);
    }, [options.resourceId, options.resourceType]);
    useEffect(() => {
        if (!options.defaultOpen || appliedDefaultOpenRef.current)
            return;
        appliedDefaultOpenRef.current = true;
        handleOpenChange(true);
    }, [handleOpenChange, options.defaultOpen]);
    const handleShareTabChange = useCallback((value) => {
        setActiveShareTab(value);
        options.shareTabs?.onValueChange?.(value);
    }, [options.shareTabs]);
    const handleVisibilityChange = useCallback((next) => {
        if (!canManage) {
            setShareError("Only owners and admins can change access.");
            return Promise.resolve();
        }
        const requestId = visibilityGuard.begin();
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (prev) => (prev ? { ...prev, visibility: next } : prev));
        setVisibilityOverride(next);
        return new Promise((resolve, reject) => {
            setVisibility.mutate({
                resourceType: options.resourceType,
                resourceId: options.resourceId,
                visibility: next,
            }, {
                onSuccess: (result) => {
                    if (visibilityGuard.isLatest(requestId)) {
                        const resultVisibility = typeof result === "object" &&
                            result !== null &&
                            "visibility" in result &&
                            result.visibility;
                        optimisticallyUpdateShareCache(queryClient, shareQueryKey, (prev) => prev
                            ? {
                                ...prev,
                                visibility: resultVisibility ?? next,
                            }
                            : prev);
                    }
                    sharesQuery
                        .refetch()
                        .then(() => resolve())
                        .catch(reject)
                        .finally(() => {
                        if (visibilityGuard.isLatest(requestId)) {
                            setVisibilityOverride(null);
                        }
                    });
                },
                onError: (error) => {
                    if (visibilityGuard.isLatest(requestId)) {
                        setVisibilityOverride(null);
                        rollbackShareCache(queryClient, shareQueryKey, previous);
                    }
                    reject(error);
                },
            });
        });
    }, [
        options.resourceId,
        options.resourceType,
        queryClient,
        setVisibility,
        shareQueryKey,
        sharesQuery,
        canManage,
        visibilityGuard,
    ]);
    const policy = data?.policy ?? {
        allowPublic: true,
        requireOrgMemberForUserShares: false,
    };
    const visibility = visibilityOverride ?? data?.visibility ?? "private";
    const triggerVisibility = visibilityOverride ?? (data ? (data.visibility ?? "private") : null);
    // Keep draft and optimistic state in the controller so closing and reopening
    // the popover cannot drop an in-flight mutation or an unsent invite.
    const [role, setRole] = useState("viewer");
    useEffect(() => {
        const allowedRoles = options.allowedRoles;
        if (!allowedRoles || allowedRoles.includes(role))
            return;
        const fallbackRole = allowedRoles[0];
        if (fallbackRole)
            setRole(fallbackRole);
    }, [options.allowedRoles, role]);
    const [notifyPeople, setNotifyPeople] = useState(true);
    const [shareMessage, setShareMessage] = useState("");
    const [messageOpen, setMessageOpen] = useState(false);
    const [suggestionsOpen, setSuggestionsOpen] = useState(false);
    const [pendingAdds, setPendingAdds] = useState([]);
    const [pendingRemoves, setPendingRemoves] = useState(new Set());
    const [roleOverrides, setRoleOverrides] = useState({});
    const [inFlight, setInFlight] = useState(new Set());
    const inFlightRef = useRef(new Set());
    const addInFlight = useCallback((key) => {
        inFlightRef.current.add(key);
        setInFlight((prev) => new Set(prev).add(key));
    }, []);
    const clearInFlight = useCallback((key) => {
        inFlightRef.current.delete(key);
        setInFlight((prev) => {
            const next = new Set(prev);
            next.delete(key);
            return next;
        });
    }, []);
    useEffect(() => {
        void sharesQuery.refetch();
        // The resource identity is intentionally stable for this controller.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    const memberSearch = useShareOrgMemberSearch(inviteEmail, canManage && suggestionsOpen, {
        limit: DEFAULT_MEMBER_SUGGESTION_LIMIT,
        debounceMs: DEFAULT_MEMBER_SEARCH_DEBOUNCE_MS,
    });
    const groupsQuery = useActionQuery("list-workspace-user-groups", {}, {
        enabled: canManage && policy.supportsGroupShares === true && suggestionsOpen,
        staleTime: 30_000,
    });
    const serverShares = data?.shares ?? [];
    const shares = [
        ...serverShares
            .filter((share) => !pendingRemoves.has(keyOf(share)))
            .map((share) => ({
            ...share,
            role: roleOverrides[keyOf(share)] ?? share.role,
        })),
        ...pendingAdds.filter((pending) => !serverShares.some((share) => keyOf(share) === keyOf(pending))),
    ];
    const excludedMemberEmails = new Set();
    if (data?.ownerEmail)
        excludedMemberEmails.add(data.ownerEmail.toLowerCase());
    for (const currentShare of shares) {
        if (currentShare.principalType === "user") {
            excludedMemberEmails.add(currentShare.principalId.toLowerCase());
        }
    }
    const memberSuggestions = memberSearch.members.filter((member) => !excludedMemberEmails.has(member.email.toLowerCase()));
    const excludedGroupIds = new Set(shares
        .filter((share) => share.principalType === "group")
        .map((share) => share.principalId));
    const groupSuggestions = (Array.isArray(groupsQuery.data) ? groupsQuery.data : []).filter((group) => !excludedGroupIds.has(group.id) &&
        (!inviteEmail.trim() ||
            group.name.toLowerCase().includes(inviteEmail.trim().toLowerCase())));
    const knownMembers = memberSearch.members;
    const setInviteEmailValue = useCallback((email) => {
        setSelectedGroup(null);
        setInviteEmail(email);
    }, []);
    const selectGroup = useCallback((group) => {
        setSelectedGroup(group);
        setInviteEmail(group.name);
    }, []);
    const handleVisibility = useCallback((next) => {
        if (next === visibility)
            return;
        if (!canManage) {
            setShareError("Only owners and admins can change access.");
            return;
        }
        setShareError(null);
        void handleVisibilityChange(next).catch((error) => {
            setShareError(extractShareErrorMessage(error));
        });
    }, [canManage, handleVisibilityChange, visibility]);
    const handleHideInSearch = useCallback(() => {
        const control = options.hideInSearchControl;
        if (!control || control.pending || !canManage)
            return;
        setShareError(null);
        try {
            Promise.resolve(control.onCheckedChange(!control.checked)).catch((error) => setShareError(extractShareErrorMessage(error)));
        }
        catch (error) {
            setShareError(extractShareErrorMessage(error));
        }
    }, [canManage, options.hideInSearchControl]);
    const handleAdd = useCallback(() => {
        const trimmed = inviteEmail.trim();
        if (!trimmed || !canManage)
            return;
        const principalType = selectedGroup ? "group" : "user";
        const principalId = selectedGroup?.id ?? trimmed;
        const message = principalType === "user" && notifyPeople ? shareMessage.trim() : "";
        const optimistic = {
            id: `pending-${principalType}-${principalId}`,
            principalType,
            principalId,
            ...(selectedGroup ? { displayName: selectedGroup.name } : {}),
            role,
        };
        const key = keyOf(optimistic);
        if (inFlightRef.current.has(key))
            return;
        setShareError(null);
        setPendingAdds((previous) => [...previous, optimistic]);
        setInviteEmail("");
        setSelectedGroup(null);
        setShareMessage("");
        setMessageOpen(false);
        setSuggestionsOpen(false);
        addInFlight(key);
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached ? { ...cached, shares: [...cached.shares, optimistic] } : cached);
        share.mutate({
            resourceType: options.resourceType,
            resourceId: options.resourceId,
            principalType,
            principalId,
            role,
            notify: principalType === "user" && notifyPeople,
            resourceUrl: getNotificationUrl(options.shareUrl),
            ...(message ? { message } : {}),
        }, {
            onSuccess: () => {
                void sharesQuery.refetch().then(() => {
                    setPendingAdds((previous) => previous.filter((item) => item.id !== optimistic.id));
                    clearInFlight(key);
                });
            },
            onError: (error) => {
                rollbackShareCache(queryClient, shareQueryKey, previous);
                setPendingAdds((previous) => previous.filter((item) => item.id !== optimistic.id));
                clearInFlight(key);
                setInviteEmail(trimmed);
                setSelectedGroup(selectedGroup);
                setShareMessage((current) => current || message);
                setMessageOpen((current) => current || Boolean(message));
                setShareError(extractShareErrorMessage(error));
            },
        });
    }, [
        addInFlight,
        canManage,
        clearInFlight,
        inviteEmail,
        notifyPeople,
        options.resourceId,
        options.resourceType,
        options.shareUrl,
        role,
        selectedGroup,
        shareMessage,
        share,
        queryClient,
        shareQueryKey,
        sharesQuery,
    ]);
    const handleChangeRole = useCallback((currentShare, next) => {
        if (currentShare.role === next)
            return;
        if (!canManage) {
            setShareError("Only owners and admins can change access.");
            return;
        }
        const key = keyOf(currentShare);
        if (inFlightRef.current.has(key))
            return;
        setRoleOverrides((previous) => ({ ...previous, [key]: next }));
        addInFlight(key);
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached
            ? {
                ...cached,
                shares: cached.shares.map((share) => keyOf(share) === key ? { ...share, role: next } : share),
            }
            : cached);
        share.mutate({
            resourceType: options.resourceType,
            resourceId: options.resourceId,
            principalType: currentShare.principalType,
            principalId: currentShare.principalId,
            role: next,
            notify: false,
        }, {
            onSuccess: () => {
                void sharesQuery.refetch().then(() => {
                    setRoleOverrides((previous) => {
                        const { [key]: _removed, ...rest } = previous;
                        return rest;
                    });
                    clearInFlight(key);
                });
            },
            onError: (error) => {
                rollbackShareCache(queryClient, shareQueryKey, previous);
                setRoleOverrides((previous) => {
                    const { [key]: _removed, ...rest } = previous;
                    return rest;
                });
                clearInFlight(key);
                setShareError(extractShareErrorMessage(error));
            },
        });
    }, [
        addInFlight,
        canManage,
        clearInFlight,
        options.resourceId,
        options.resourceType,
        queryClient,
        shareQueryKey,
        share,
        sharesQuery,
    ]);
    const handleRemove = useCallback((currentShare) => {
        if (!canManage) {
            setShareError("Only owners and admins can change access.");
            return;
        }
        const key = keyOf(currentShare);
        if (inFlightRef.current.has(key))
            return;
        setPendingRemoves((previous) => new Set(previous).add(key));
        addInFlight(key);
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached
            ? {
                ...cached,
                shares: cached.shares.filter((share) => keyOf(share) !== key),
            }
            : cached);
        unshare.mutate({
            resourceType: options.resourceType,
            resourceId: options.resourceId,
            principalType: currentShare.principalType,
            principalId: currentShare.principalId,
        }, {
            onSuccess: () => {
                void sharesQuery.refetch().then(() => {
                    setPendingRemoves((previous) => {
                        const next = new Set(previous);
                        next.delete(key);
                        return next;
                    });
                    clearInFlight(key);
                });
            },
            onError: (error) => {
                rollbackShareCache(queryClient, shareQueryKey, previous);
                setPendingRemoves((previous) => {
                    const next = new Set(previous);
                    next.delete(key);
                    return next;
                });
                clearInFlight(key);
                setShareError(extractShareErrorMessage(error));
            },
        });
    }, [
        addInFlight,
        canManage,
        clearInFlight,
        options.resourceId,
        options.resourceType,
        queryClient,
        shareQueryKey,
        sharesQuery,
        unshare,
    ]);
    return {
        open,
        handleOpenChange,
        activeShareTab,
        handleShareTabChange,
        inviteEmail,
        setInviteEmail: setInviteEmailValue,
        sharesQuery,
        visibilityOverride,
        handleVisibilityChange,
        data,
        policy,
        visibility,
        triggerVisibility,
        canManage,
        role,
        setRole,
        notifyPeople,
        shareMessage,
        setShareMessage,
        messageOpen,
        setMessageOpen,
        setNotifyPeople,
        shareError,
        setShareError,
        suggestionsOpen,
        setSuggestionsOpen,
        inFlight,
        memberSearch,
        memberSuggestions,
        knownMembers,
        shares,
        handleVisibility,
        handleHideInSearch,
        handleAdd,
        handleChangeRole,
        handleRemove,
        groupSuggestions,
        selectedGroup,
        selectGroup,
    };
}
function keyOf(share) {
    return `${share.principalType}:${share.principalId}`;
}
function getNotificationUrl(explicit) {
    if (explicit)
        return explicit;
    if (typeof window === "undefined")
        return undefined;
    return window.location.href;
}
